pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialPastBlockTime, uint256 laterTimestamp) public {
        // Ensure timestamps are in a reasonable range
        laterTimestamp = bound(laterTimestamp, 1, 2**40);
        initialPastBlockTime = bound(initialPastBlockTime, 0, laterTimestamp - 1);

        // Set the initial pastBlockTime via a successful call
        vm.warp(initialPastBlockTime);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        if (initialPastBlockTime > 0) {
            assertTrue(success1);
        }

        uint256 pastBlockTimeBefore = c.pastBlockTime();

        // Now call fallback at laterTimestamp
        vm.warp(laterTimestamp);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        if (success2) {
            // If the call succeeded, pastBlockTime must have strictly increased
            assertTrue(c.pastBlockTime() > pastBlockTimeBefore);
        } else {
            // If the call reverted, pastBlockTime must remain unchanged
            assertTrue(c.pastBlockTime() == pastBlockTimeBefore);
        }
    }
}

