import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum) public {
        // Bound block number to a reasonable range
        blockNum = bound(blockNum, 1, 1000);

        // Ensure we start with a pastBlockTime that is not zero and less than the current block timestamp
        // We'll use vm.warp to set block.timestamp
        vm.warp(blockNum + 1000); // Ensure timestamp > pastBlockTime initially (pastBlockTime = 0)
        vm.deal(address(this), 10 ether);

        // Call fallback with 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Only consider successful calls
        vm.assume(success);

        // The rule: if block.number % 15 != 0, the contract balance should be 0 after the call (since it transfers out)
        // If block.number % 15 == 0, the contract retains the balance
