import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp) public {
        // Ensure timestamp > pastBlockTime (initial 0)
        vm.assume(timestamp > 0);
        vm.warp(timestamp);

        // Ensure block number such that condition is relevant
        // We'll call fallback and check balance based on block.number mod 15
        vm.deal(address(this), 10 ether);

        // Record block number before call
        uint256 blockNumBefore = block.number;

        // Call fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Only consider successful calls
        if (success) {
            // After a successful fallback, if block.number % 15 == 0 (original condition true), 
            // the balance is transferred out; otherwise it stays.
            // But the mutant condition is block.number % 15 != 0.
            // So the rule: if block.number % 15 != 0, then balance == 0; else balance == 10 ether (since no transfer)
            // Actually after successful fallback, the contract receives 10 ether.
            // In reference: transfer only when block.number % 15 == 0 → balance 0 in that case.
            // Here we check the condition: after call, balance should be 0 exactly when block.number % 15 == 0 (original condition)
            // Or equivalently: balance > 0 iff block.number % 15 != 0.
            uint256 contractBalance = address(c).balance;
            if (block.number % 15 == 0) {
                assertTrue(contractBalance == 0, "Balance should be zero when block.number % 15 == 0");
            } else {
                assertTrue(contractBalance > 0, "Balance should be positive when block.number % 15 != 0");
            }
        }
    }
}

