contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp, uint256 pastBlockTime) public {
        // Bound inputs to reasonable ranges
        blockNumber = bound(blockNumber, 1, 1000);
        timestamp = bound(timestamp, 1, 1000);
        pastBlockTime = bound(pastBlockTime, 0, 999);

        // Ensure valid timestamp condition for fallback
        vm.assume(timestamp > pastBlockTime);

        // Set block parameters
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Fund contract with more than 10 ether
        vm.deal(address(c), 20 ether);
        uint256 balBefore = address(c).balance;

        // Call fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balAfter = address(c).balance;

        // The rule: if the condition is true (block.number % 15 == 0), balance stays same (transfer doesn't happen)
        // For reference: if block.number % 15 == 0, transfer occurs -> balance = 0 (after transfer, all sent back)
        // Buggy: if block.number % 15 != 0, transfer occurs -> balance = 0
        // We check: the behavior matches the reference condition
        if (blockNumber % 15 == 0) {
            // Reference: transfer happens -> balance becomes 0
            // (after receiving 10 and sending all back)
            assertTrue(balAfter == 0 ether);
        } else {
            // Reference: no transfer -> balance = balBefore + 10 ether
            assertTrue(balAfter == balBefore + 10 ether);
        }
    }
}

