pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _blocksToWait, uint256 _timestampDelta) public {
        // Bound inputs to valid ranges
        uint256 blocksToWait = bound(_blocksToWait, 1, 100);
        uint256 timestampDelta = bound(_timestampDelta, 1, 1000);

        // Ensure block conditions
        vm.roll(block.number + blocksToWait);
        vm.warp(block.timestamp + timestampDelta);

        // Deal 10 ether to this contract to send
        uint256 initialBalance = address(c).balance;
        vm.deal(address(this), 10 ether);

        // Call fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        // General rule: if call succeeded and block.number % 15 == 0, balance decreases by 1 ether (buggy) or entire balance (correct)
        // Actually we need a rule that distinguishes them: 
        // Correct: transfer entire balance => new balance = 0
        // Buggy: transfer 1 ether => new balance = old balance + 10 ether - 1 ether
        uint256 newBalance = address(c).balance;
        if (block.number % 15 == 0) {
            // In correct version: newBalance = 0, in buggy: newBalance = initialBalance + 10 ether - 1 ether
            assertTrue(newBalance == 0 || newBalance == initialBalance + 10 ether - 1 ether);
        } else {
            // Otherwise balance increased by 10 ether
            assertTrue(newBalance == initialBalance + 10 ether);
        }
